# Generated by scripts/build_skill.py; edit src/compass_c instead.
"""Finite, advisory experiment proposals and explicit Bayesian model revisions.

Every probability, likelihood, payoff, cost and source is supplied by the caller.
No experiment is executed and no notebook or evidence source is modified.
"""

from __future__ import annotations

import copy
import math
import re
from datetime import datetime
from fractions import Fraction

from core import CompassError, number, strings, text

_LIMITATIONS = (
    "Conditional expected value under caller-supplied payoffs, priors and likelihoods; "
    "not empirical validation or action authorization. Larger comparable payoffs are preferred. "
    "Costs use the model's value_unit and durations use the supplied duration_unit. "
    "Each proposal covers one observation with mutually exclusive exhaustive outcomes; "
    "candidates are alternatives, not an experiment sequence or joint information model. "
    "Supplied probability vectors within 1e-10 of one are normalized only for rounding. "
    "Exact decimal arithmetic determines winners; displayed numbers are rounded. "
    "Sources and likelihoods are preserved as supplied, not independently verified. "
    "Hard constraints, omitted scenarios, changing payoffs and execution permissions remain "
    "the owner's responsibility. For sequential observations, the owner must supply "
    "likelihoods appropriate conditional on the evidence already used; reusing a likelihood "
    "does not establish conditional independence."
)


def _fields(parameters, required, optional=()):
    # Runtime-local import lets the calculation registry dispatch here without a cycle.
    from calculations import fields

    fields(parameters, required, optional)


def _metadata(value):
    if not strings(value["provenance"], "provenance"):
        raise CompassError("INVALID_INPUT", "Provide nonempty provenance")
    strings(value["assumptions"], "assumptions")


def _probabilities(value, size, field):
    from calculations import _probability_vector

    parsed = [Fraction(str(p)) for p in _probability_vector(value, size, field)]
    total = sum(parsed)
    return [p / total for p in parsed]


def _model(value):
    from calculations import _comparison_model

    _fields(
        value,
        [
            "actions",
            "scenarios",
            "payoffs",
            "probabilities",
            "value_unit",
            "provenance",
            "assumptions",
        ],
        ["probabilities_exact"],
    )
    actions, scenarios, payoffs = _comparison_model(value)
    probabilities = _probabilities(value["probabilities"], len(scenarios), "probabilities")
    text(value["value_unit"], "value_unit", limit=2000)
    _metadata(value)
    if "probabilities_exact" in value:
        exact = value["probabilities_exact"]
        if type(exact) is not list or len(exact) != len(scenarios):
            raise CompassError("INVALID_INPUT", "One exact probability per scenario required")
        parsed = []
        common_denominator = 1
        for supplied, displayed in zip(exact, value["probabilities"], strict=True):
            text(supplied, "probabilities_exact", limit=1024)
            if re.fullmatch(r"-?(?:0|[1-9][0-9]*)(?:/[1-9][0-9]*)?", supplied) is None:
                raise CompassError("INVALID_INPUT", "Exact probabilities require integer fractions")
            try:
                probability = Fraction(supplied)
            except (ValueError, ZeroDivisionError) as exc:
                raise CompassError("INVALID_INPUT", "Invalid exact probability") from exc
            if not 0 <= probability <= 1 or float(probability) != float(displayed):
                raise CompassError(
                    "INVALID_INPUT", "Exact probability must match its displayed probability"
                )
            common_denominator = math.lcm(common_denominator, probability.denominator)
            if common_denominator.bit_length() > 3400:
                raise CompassError("INVALID_INPUT", "Exact probability precision exceeds bounds")
            parsed.append(probability)
        if sum(parsed) != 1:
            raise CompassError("INVALID_INPUT", "Exact probabilities must sum to one")
        probabilities = parsed
    return actions, scenarios, [[Fraction(str(p)) for p in row] for row in payoffs], probabilities


def _experiment(value, scenario_count):
    _fields(
        value,
        [
            "id",
            "question",
            "protocol",
            "outcomes",
            "likelihoods",
            "cost",
            "duration",
            "provenance",
            "assumptions",
        ],
    )
    for field in ("id", "question", "protocol"):
        text(value[field], field, limit=2000 if field == "id" else 12000)
    outcomes = strings(value["outcomes"], "outcomes", maximum=32)
    if not outcomes or len(outcomes) != len(set(outcomes)):
        raise CompassError("INVALID_INPUT", "Provide nonempty unique outcome names")
    likelihoods = value["likelihoods"]
    if type(likelihoods) is not list or len(likelihoods) != scenario_count:
        raise CompassError("INVALID_INPUT", "One likelihood row per scenario required")
    parsed = [_probabilities(row, len(outcomes), "likelihoods") for row in likelihoods]
    cost = Fraction(str(number(value["cost"], "cost", 0, 1e12)))
    duration = Fraction(str(number(value["duration"], "duration", 0, 1e12)))
    _metadata(value)
    return outcomes, parsed, cost, duration


def _scores(actions, payoffs, probabilities):
    values = [
        sum(p * value for p, value in zip(probabilities, row, strict=True)) for row in payoffs
    ]
    best = max(values)
    return best, [action for action, value in zip(actions, values, strict=True) if value == best]


def _metric(name, value):
    return {name: float(value), name + "_exact": str(value)}


def _branches(actions, payoffs, probabilities, outcomes, likelihoods, prior_winners):
    # Individually finite decimals can create an enormous common denominator when
    # many independently rounded likelihood vectors are normalized. Bound their
    # combined exact precision before Bayesian sums or integer rendering.
    common_denominator = 1
    for vector in [probabilities, *likelihoods]:
        for probability in vector:
            common_denominator = math.lcm(common_denominator, probability.denominator)
            if common_denominator.bit_length() > 8192:
                raise CompassError("INVALID_INPUT", "Combined probability precision exceeds bounds")
    branches = []
    information_value = Fraction(0)
    decision_change_probability = Fraction(0)
    for index, outcome in enumerate(outcomes):
        weights = [
            probability * row[index]
            for probability, row in zip(probabilities, likelihoods, strict=True)
        ]
        chance = sum(weights)
        branch = {
            "outcome": outcome,
            "possible": bool(chance),
            **_metric("probability", chance),
            "posterior_probabilities": None,
            "posterior_probabilities_exact": None,
            "expected_value": None,
            "expected_value_exact": None,
            "expected_value_winners": [],
            "preference_changed": False,
            "prior_winners_rejected": [],
        }
        if chance:
            posterior = [weight / chance for weight in weights]
            expected, winners = _scores(actions, payoffs, posterior)
            changed = winners != prior_winners
            branch.update(
                {
                    "posterior_probabilities": [float(p) for p in posterior],
                    "posterior_probabilities_exact": [str(p) for p in posterior],
                    **_metric("expected_value", expected),
                    "expected_value_winners": winners,
                    "preference_changed": changed,
                    "prior_winners_rejected": [a for a in prior_winners if a not in winners],
                }
            )
            information_value += chance * expected
            if changed:
                decision_change_probability += chance
        branches.append(branch)
    return branches, information_value, decision_change_probability


def propose_experiments(parameters: dict) -> dict:
    """Compare bounded single-observation experiments against doing no experiment."""
    _fields(parameters, ["model", "experiments", "budget", "max_duration", "duration_unit"])
    actions, scenarios, payoffs, probabilities = _model(parameters["model"])
    budget = Fraction(str(number(parameters["budget"], "budget", 0, 1e12)))
    max_duration = Fraction(str(number(parameters["max_duration"], "max_duration", 0, 1e12)))
    duration_unit = text(parameters["duration_unit"], "duration_unit", limit=2000)
    candidates = parameters["experiments"]
    if type(candidates) is not list or len(candidates) > 32:
        raise CompassError("INVALID_INPUT", "Provide a list of at most 32 experiments")
    parsed = [_experiment(candidate, len(scenarios)) for candidate in candidates]
    if len({candidate["id"] for candidate in candidates}) != len(candidates):
        raise CompassError("INVALID_INPUT", "Experiment IDs must be unique")

    baseline, prior_winners = _scores(actions, payoffs, probabilities)
    perfect_value = sum(
        probability * max(row[index] for row in payoffs)
        for index, probability in enumerate(probabilities)
    )
    changing_scenarios = []
    for index, (scenario, probability) in enumerate(zip(scenarios, probabilities, strict=True)):
        scenario_best = max(row[index] for row in payoffs)
        scenario_winners = [
            action
            for action, row in zip(actions, payoffs, strict=True)
            if row[index] == scenario_best
        ]
        if probability and scenario_winners != prior_winners:
            changing_scenarios.append(scenario)

    rows = []
    feasible = []
    for candidate, (outcomes, likelihoods, cost, duration) in zip(candidates, parsed, strict=True):
        branches, information_value, changed = _branches(
            actions, payoffs, probabilities, outcomes, likelihoods, prior_winners
        )
        sample_value = information_value - baseline
        net_value = sample_value - cost
        status = (
            "over_budget"
            if cost > budget
            else "over_duration"
            if duration > max_duration
            else "no_decision_value"
            if sample_value <= 0
            else "net_value_not_positive"
            if net_value <= 0
            else "informative_within_bounds"
        )
        if status == "informative_within_bounds":
            feasible.append((candidate["id"], net_value))
        rows.append(
            {
                "id": candidate["id"],
                "experiment": copy.deepcopy(candidate),
                "status": status,
                "within_budget": cost <= budget,
                "within_duration": duration <= max_duration,
                "outcomes": branches,
                **_metric("expected_value_with_information", information_value),
                **_metric("sample_information_value", sample_value),
                **_metric("net_information_value", net_value),
                **_metric("expected_value_after_cost", information_value - cost),
                **_metric("decision_change_probability", changed),
            }
        )
    best = max((value for _, value in feasible), default=Fraction(0))
    return {
        "calculation": "experiment",
        "result": {
            "model": copy.deepcopy(parameters["model"]),
            "baseline": {
                **_metric("expected_value", baseline),
                "expected_value_winners": prior_winners,
            },
            **_metric("perfect_information_value", perfect_value - baseline),
            "decision_changing_scenarios": changing_scenarios,
            "experiments": rows,
            "budget": float(budget),
            "max_duration": float(max_duration),
            "duration_unit": duration_unit,
            "proposed_experiment_ids": [name for name, value in feasible if value == best],
            "proposal_is_sequence": False,
            "criterion_chosen_by_tool": False,
        },
        "limitations": _LIMITATIONS,
        "action_permission": "not_granted",
    }


def revise_model(parameters: dict) -> dict:
    """Return a Bayesian update from one explicit observation without recording it."""
    _fields(parameters, ["model", "experiment", "observation"])
    actions, scenarios, payoffs, probabilities = _model(parameters["model"])
    outcomes, likelihoods, _, _ = _experiment(parameters["experiment"], len(scenarios))
    observation = parameters["observation"]
    _fields(observation, ["outcome", "source", "observed_at", "note"])
    for field in ("outcome", "source", "observed_at", "note"):
        text(observation[field], field)
    if observation["outcome"] not in outcomes:
        raise CompassError("INVALID_INPUT", "Observed outcome is not in the experiment")
    try:
        observed_at = datetime.fromisoformat(observation["observed_at"])
    except ValueError as exc:
        raise CompassError("INVALID_INPUT", "observed_at must be an ISO timestamp") from exc
    if observed_at.utcoffset() is None:
        raise CompassError("INVALID_INPUT", "observed_at must include a timezone")

    _, prior_winners = _scores(actions, payoffs, probabilities)
    branches, _, _ = _branches(
        actions, payoffs, probabilities, outcomes, likelihoods, prior_winners
    )
    branch = branches[outcomes.index(observation["outcome"])]
    if not branch["possible"]:
        raise CompassError(
            "IMPOSSIBLE_OBSERVATION",
            "The observation has zero probability under the supplied model; "
            "inspect the prior, likelihoods and observation before proposing another model",
        )
    revised = copy.deepcopy(parameters["model"])
    revised["probabilities"] = branch["posterior_probabilities"]
    revised["probabilities_exact"] = branch["posterior_probabilities_exact"]
    try:
        _model(revised)
    except CompassError as exc:
        raise CompassError(
            "INVALID_INPUT", "Posterior precision exceeds reusable model bounds"
        ) from exc
    return {
        "calculation": "update_beliefs",
        "result": {
            "prior_model": copy.deepcopy(parameters["model"]),
            "model": revised,
            "experiment": copy.deepcopy(parameters["experiment"]),
            "observation": copy.deepcopy(observation),
            "evidence_probability": branch["probability"],
            "evidence_probability_exact": branch["probability_exact"],
            "prior_winners": prior_winners,
            "posterior_winners": branch["expected_value_winners"],
            "preference_changed": branch["preference_changed"],
            "prior_winners_rejected": branch["prior_winners_rejected"],
            "source_verified": False,
            "criterion_chosen_by_tool": False,
        },
        "limitations": _LIMITATIONS,
        "action_permission": "not_granted",
    }
